class PrimeUtils:
    _divisors = {
        1: {1: True},
        2: {1: True, 2: True},
    }
    _primes = {}

    @staticmethod
    def primes(limit):
        import math
        limit = int(limit)
        size = (limit >> 3) + 1
        a = bytearray(b'U' * size)
        a[0] = ord('S')
        i = 3
        while i * i < limit:
            if a[i >> 3] & (1 << (i % 8)):
                pass
            else:
                k = i
                while k * i < limit:
                    n = k * i
                    a[n >> 3] |= (1 << (n % 8))
                    k += 1
            i += 2
        yield 2
        i = 3
        while i < limit:
            if not (a[i >> 3] & (1 << (i % 8))):
                yield i
            i += 2

    @classmethod
    def divisors(cls, n, lp=2):
        if n in cls._divisors:
            return cls._divisors[n]
        if not cls._primes:
            primes = {}
            for prime in cls.primes(1e3):
                primes[prime] = prime
            cls._primes = primes
        r = {}
        for p in cls._primes:
            if p >= lp:
                if n < p * p:
                    r = {1: True, n: True}
                    break
                elif n % p == 0:
                    for pre in [1, p]:
                        for nxt in cls.divisors(n // p, p).keys():
                            r[nxt * pre] = True
                    break
        cls._divisors[n] = r
        return cls._divisors[n]


